#!/bin/bash
# Hash fixes of eb31453ff (build 2985-fb1636c, develop ef4e7e812 merged): every pair below is one key for the index
# and must now give SAME (the slave holds T1 back with the gate row; a missed dependency shows as -670 and a lost row).
# t01..t07 are the 10-31 survey defects, t08..t12 similar cases (trailing NUL vs space, composite and euckr VARCHAR).
export OUT_ROOT=${OUT_ROOT:-$HOME/ha_bench_tool/log/pair_order_$(date +%Y%m%d_%H%M)_hashfix}
T=~/ha_bench_tool/bin/pair_order_test.sh
$T t01_varbit "drop table if exists ph_vb; create table ph_vb (k bit varying(64) primary key, id int); insert into ph_vb values (B'1', 1);" "delete from ph_vb where id=1" "insert into ph_vb values (B'10', 2)" "gate" "select id, k from ph_vb order by 1"
$T t02_varbit_7_8 "drop table if exists ph_vb2; create table ph_vb2 (k bit varying(64) primary key, id int); insert into ph_vb2 values (B'1010101', 1);" "delete from ph_vb2 where id=1" "insert into ph_vb2 values (B'10101010', 2)" "gate" "select id, k from ph_vb2 order by 1"
$T t03_str_mid_nul_iso "drop table if exists ph_s1; create table ph_s1 (k varchar(10) primary key, id int); insert into ph_s1 values ('a b', 1);" "delete from ph_s1 where id=1" "insert into ph_s1 values ('a'||chr(0)||'b', 2)" "gate" "select id, hex(k) from ph_s1 order by 1"
$T t04_str_mid_nul_utf8ko "drop table if exists ph_s2; create table ph_s2 (k varchar(10) collate utf8_ko_cs primary key, id int); insert into ph_s2 values (_utf8'a b', 1);" "delete from ph_s2 where id=1" "insert into ph_s2 values (_utf8'a' || chr(0 using utf8) || _utf8'b', 2)" "gate" "select id, hex(k) from ph_s2 order by 1"
$T t05_str_euckr_char "drop table if exists ph_s3; create table ph_s3 (k char(10) collate euckr_bin primary key, id int); insert into ph_s3 values (_euckr'a', 1);" "delete from ph_s3 where id=1" "insert into ph_s3 values (_euckr'a' || chr(0 using euckr) || chr(41377 using euckr), 2)" "gate" "select id, hex(k) from ph_s3 order by 1"
$T t06_double_nan "drop table if exists ph_nan; create table ph_nan (k double primary key, id int); insert into ph_nan values (cast('nan' as double), 1);" "delete from ph_nan where id=1" "insert into ph_nan values (1.0, 2)" "gate" "select id, k from ph_nan order by 1"
$T t07_nan_then_insert "drop table if exists ph_nan2; create table ph_nan2 (k double primary key, id int); insert into ph_nan2 values (1.0, 1);" "delete from ph_nan2 where id=1" "insert into ph_nan2 values (cast('nan' as double), 2)" "gate" "select id, k from ph_nan2 order by 1"
$T t08_varchar_trailing_nul "drop table if exists ph_t1; create table ph_t1 (k varchar(10) primary key, id int); insert into ph_t1 values ('a ', 1);" "delete from ph_t1 where id=1" "insert into ph_t1 values ('a'||chr(0), 2)" "gate" "select id, hex(k) from ph_t1 order by 1"
$T t09_varchar_trailing_nul_space "drop table if exists ph_t2; create table ph_t2 (k varchar(10) collate utf8_bin primary key, id int); insert into ph_t2 values (_utf8'a  ', 1);" "delete from ph_t2 where id=1" "insert into ph_t2 values (_utf8'a' || chr(0 using utf8) || _utf8' ', 2)" "gate" "select id, hex(k) from ph_t2 order by 1"
$T t10_euckr_varchar_nul "drop table if exists ph_t3; create table ph_t3 (k varchar(10) collate euckr_bin primary key, id int); insert into ph_t3 values (_euckr'a', 1);" "delete from ph_t3 where id=1" "insert into ph_t3 values (_euckr'a' || chr(0 using euckr), 2)" "gate" "select id, hex(k) from ph_t3 order by 1"
$T t11_varbit_composite "drop table if exists ph_c1; create table ph_c1 (k bit varying(64), j int, id int, primary key (k, j)); insert into ph_c1 values (B'1', 7, 1);" "delete from ph_c1 where id=1" "insert into ph_c1 values (B'10', 7, 2)" "gate" "select id, k, j from ph_c1 order by 1"
$T t12_str_nul_composite "drop table if exists ph_c2; create table ph_c2 (k varchar(10), j int, id int, primary key (k, j)); insert into ph_c2 values ('a b', 7, 1);" "delete from ph_c2 where id=1" "insert into ph_c2 values ('a'||chr(0)||'b', 7, 2)" "gate" "select id, hex(k), j from ph_c2 order by 1"
echo ALL_DONE $OUT_ROOT
